// 由 build-feature.mjs 从 preview/app.css 抽出（不要手改）
export const CSS = ":host{display:block;height:100%;min-height:0;overflow:hidden}\n.mcp-wrap{display:flex;flex-direction:column;height:100%;min-height:0}\n/* 3D 建筑预览 · 产品样式\r\n *\r\n * 设计依据 = ModMind 交接包里的 `ui-design-studio` skill（`ui界面/SKILL.md` + `design-system.md`）。\r\n * 两条硬规则贯穿本文件：\r\n *\r\n *   ① **令牌单一来源，不硬编码颜色/间距**。颜色一律走 `--mm-*`，而 `--mm-*` 又优先取**宿主主题令牌**\r\n *      `--theme-*`（与承包方两条功能包用的是同一层别名，见归档 `代码/共享/modules.css`）。\r\n *      CSS 自定义属性会**穿过 Shadow DOM 继承**，所以功能包里能直接拿到宿主的主题值 ⇒ 面板自动跟随\r\n *      宿主的浅色/深色主题，不会出现\"宿主浅色、面板深色\"的割裂。\r\n *   ② 间距只允许 4pt 倍数；圆角同页只留 3 档（控件 8 / 卡片 12 / 胶囊 full）；字号走 12/14/16/20 阶梯。\r\n *\r\n * 可访问性（skill §7 + accessibility）：正文 ≥4.5:1、大字与控件边界 ≥3:1；\r\n * `:focus-visible` 一律可见（**禁止裸删 outline**）；动效尊重 `prefers-reduced-motion`。\r\n * 实测对比度见 `.work/check-contrast.mjs` 的输出（不是\"声称通过\"）。\r\n */\r\n\r\n:host{\r\n  /* ============ 颜色：宿主主题优先，浅色兜底 ============ */\r\n  --mm-canvas: var(--theme-canvas, #f6f8fb);            /* 页面/视口底 */\r\n  --mm-surface: var(--theme-surface, #ffffff);          /* 卡片、输入框底 */\r\n  --mm-bg-2: var(--theme-bg-secondary, #f1f5f9);        /* 分区底、hover 底、表头底 */\r\n  --mm-line: var(--theme-line, #e2e8f0);                /* 分隔线（装饰性） */\r\n  --mm-text-1: var(--theme-text-primary, var(--theme-text, #0f172a));\r\n  --mm-text-2: var(--theme-text-secondary, #475569);    /* 次要文字、表头文字 */\r\n  --mm-muted: var(--theme-muted, #64748b);              /* 占位、辅助小字 */\r\n  --mm-accent: var(--theme-accent, #2563eb);            /* 主色：只表示\"可点击/已选中\" */\r\n  --mm-action: var(--theme-action, #1d4ed8);            /* 主按钮底 */\r\n  --mm-on-action: var(--theme-on-action, #ffffff);\r\n  --mm-danger: var(--theme-danger, #b91c1c);\r\n  --mm-warning: var(--theme-warning, #b45309);\r\n  --mm-scrim: var(--theme-scrim, rgba(15, 23, 42, .45));\r\n  /* 语义「文字」变体：基础语义色对白底普遍 <4.5:1，作文字时必须用这些 */\r\n  --mm-ok-text: #15803d;\r\n  --mm-warn-text: #b45309;\r\n  --mm-err-text: #b91c1c;\r\n  /* 控件边界：装饰线（--mm-line）只有 1.2:1，不满足 1.4.11 的 3:1。\r\n     这里从**正文色**派生出边界（两种主题下都保证可辨识）；不支持 color-mix 的宿主用前一行的兜底。 */\r\n  --mm-ctl-border: #64748b;\r\n  --mm-ctl-border: color-mix(in srgb, var(--mm-text-1) 60%, transparent);\r\n  --mm-accent-tint: #e8f0fe;\r\n  --mm-accent-tint: color-mix(in srgb, var(--mm-accent) 12%, var(--mm-surface));\r\n\r\n  /* ============ 间距（4pt 基准，禁止非倍数） ============ */\r\n  --sp-1: 4px; --sp-2: 8px; --sp-3: 12px; --sp-4: 16px; --sp-6: 24px; --sp-8: 32px;\r\n\r\n  /* ============ 圆角（同页 3 档） ============ */\r\n  --r-ctl: 8px;          /* 控件 */\r\n  --r-card: 12px;        /* 卡片 / 对话框 */\r\n  --r-full: 9999px;\r\n\r\n  /* ============ 字体阶梯 ============ */\r\n  --fs-xs: 12px; --fs-sm: 14px; --fs-md: 16px; --fs-lg: 20px;\r\n  --font-ui: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\r\n  --font-num: \"SF Mono\", \"JetBrains Mono\", Consolas, \"Cascadia Mono\", monospace;\r\n\r\n  /* ============ 阴影：只表达层级，不做装饰（深色模式由宿主令牌自然变淡） ============ */\r\n  --sh-sm: 0 1px 2px rgba(15, 23, 42, .06);\r\n  --sh-md: 0 4px 12px rgba(15, 23, 42, .08);\r\n  --sh-lg: 0 12px 32px rgba(15, 23, 42, .12);\r\n\r\n  /* ============ 动效 ============ */\r\n  --t-fast: 120ms; --t-base: 200ms; --t-slow: 320ms;\r\n\r\n  /* ============ 层级 ============ */\r\n  --z-drop: 1000; --z-sticky: 1100; --z-modal: 2000;\r\n\r\n  color-scheme: light dark;\r\n}\r\n\r\n*{ box-sizing: border-box; }\r\nhtml, body{ margin: 0; height: 100%; background: var(--mm-canvas); color: var(--mm-text-1);\r\n  font: var(--fs-sm)/1.5 var(--font-ui); overflow: hidden; }\r\nbutton, input, select, textarea{ font: inherit; color: inherit; }\r\n\r\n/* ---------- 焦点：一律可见（skill §7，禁止裸删 outline） ---------- */\r\n:focus-visible{ outline: 2px solid var(--mm-accent); outline-offset: 1px; border-radius: var(--r-ctl); }\r\n\r\n/* ---------- 骨架 ---------- */\r\n#app{ display: flex; height:100%; flex-direction: column; background: var(--mm-canvas); }\r\n\r\n/* ---------- 顶栏（Nav：56 高 + 底边框） ---------- */\r\n#bar{ display: flex; align-items: center; gap: var(--sp-2); padding: var(--sp-2) var(--sp-3);\r\n  min-height: 56px; background: var(--mm-surface); border-bottom: 1px solid var(--mm-line); flex-wrap: wrap; }\r\n#bar .brand{ font-weight: 600; margin-right: var(--sp-1); letter-spacing: .2px; color: var(--mm-text-1); }\r\n#bar .brand small{ color: var(--mm-muted); font-weight: 400; margin-left: var(--sp-2); font-size: var(--fs-xs); }\r\n.sep{ width: 1px; height: 24px; background: var(--mm-line); margin: 0 var(--sp-1); flex: 0 0 auto; }\r\n.spacer{ flex: 1 1 auto; }\r\n.hint{ color: var(--mm-text-2); font-size: var(--fs-xs); }\r\n\r\n/* ---------- 顶栏分段（2026-10-12 布局重设计：按作用域分三段） ---------- */\r\n/* 病根：14 个常驻控件平铺在一条横条里，而它们属于四类**作用域完全不同**的东西 ⇒\r\n   「分层」紧挨着「物品栏」（毫无关系）、「项目」和「网格」看着同级；\r\n   找按钮只能\"从左边数第几个\"，不能\"先想这事属于哪一类\"。\r\n   段 = \"common region\"（同段即同类，NN/g 邻近性原则）—— 段名从 data-lb 渲染，HTML 只写一处。 */\r\n.bar-sec{ position: relative; display: inline-flex; align-items: center; gap: var(--sp-2);\r\n  /* ★ flex-wrap + 可收缩：段不可收缩时（flex:0 0 auto）它会**溢出**面板而不会换行 ——\r\n     实测闸门那种窄面板（568px）里「编辑」段的 max-content 有 600px ⇒ 按钮被推出面板右侧看不见。\r\n     改成 flex:0 1 auto + min-width:0 + 段内允许换行后：宽的时候完全不变（不需要收缩），\r\n     窄的时候段自己折行，控件**始终在面板内**。 */\r\n  flex-wrap: wrap;\r\n  padding: 2px var(--sp-2) 2px 3px; border: 1px solid var(--mm-line);\r\n  border-left: 2px solid var(--sec-c, var(--mm-line));\r\n  border-radius: var(--r-ctl); background: var(--mm-bg-2); flex: 0 1 auto; min-width: 0; }\r\n/* ⚠ 绝不要给 .bar-sec 加 overflow —— 段内三个下拉的弹层要能溢出去。\r\n   加了就是「文件下拉被截断」的复现（Q8 那条断言守着的正是它）。 */\r\n.bar-sec::before{ content: attr(data-lb); writing-mode: vertical-rl; text-orientation: upright;\r\n  font-size: 10px; font-weight: 700; letter-spacing: 1px; line-height: 1;\r\n  color: var(--sec-c, var(--mm-muted)); align-self: center; margin: 0 1px 0 2px; user-select: none; }\r\n.bar-sec[data-sec=\"proj\"]{ --sec-c: var(--mm-muted); }\r\n/* ② 编辑段是本面板的\"工作区\"，给一点底色把它和另外两段区分开（12% 主色，不抢眼） */\r\n.bar-sec[data-sec=\"edit\"]{ --sec-c: var(--mm-accent);\r\n  border-color: color-mix(in srgb, var(--mm-accent) 32%, var(--mm-line));\r\n  background: var(--mm-accent-tint); }\r\n.bar-sec[data-sec=\"view\"]{ --sec-c: var(--mm-text-2); }\r\n/* 窄面板：段是 flex item ⇒ **整段换行**，不会再出现\"「文件」单独掉到工具栏最左\"那种半截换行。\r\n   折行优先级 = DOM 顺序 = 工程 > 编辑 > 视图。\r\n   1600 以下先把品牌副标题收掉 —— 三段里唯一可以不要的东西，让它给功能让位。 */\r\n@media (max-width: 1600px){ #bar .brand small{ display: none; } }\r\n@media (max-width: 1280px){ #bar{ gap: var(--sp-1); } .bar-sec{ gap: var(--sp-1); } }\r\n\r\n/* ---------- 按钮（7 态：default/hover/focus/active/disabled/loading；error 不适用） ---------- */\r\n.btn{ min-height: 32px; padding: 0 var(--sp-3); border: 1px solid var(--mm-ctl-border); border-radius: var(--r-ctl);\r\n  background: var(--mm-surface); color: var(--mm-text-1); cursor: pointer; white-space: nowrap;\r\n  transition: background var(--t-fast) ease-out, border-color var(--t-fast) ease-out, box-shadow var(--t-fast) ease-out,\r\n              transform var(--t-fast) ease-out; }\r\n.btn:hover{ background: var(--mm-bg-2); border-color: var(--mm-accent); }\r\n.btn:active{ transform: scale(.98); background: var(--mm-bg-2); }\r\n.btn:disabled, .btn[aria-disabled=\"true\"]{ opacity: .5; cursor: not-allowed; }\r\n.btn[aria-busy=\"true\"]{ cursor: progress; }\r\n.btn.primary{ background: var(--mm-action); border-color: var(--mm-action); color: var(--mm-on-action); font-weight: 600; }\r\n.btn.primary:hover{ filter: brightness(1.08); }\r\n.btn.on{ background: var(--mm-accent-tint); border-color: var(--mm-accent); color: var(--mm-accent); font-weight: 600; }\r\n\r\n/* ---------- 工具组（1-5 切换工具，当前工具高亮） ---------- */\r\n#bar .tools{ display: inline-flex; align-items: center; gap: 2px; padding: 2px; border: 1px solid var(--mm-line);\r\n  border-radius: var(--r-ctl); background: var(--mm-bg-2); flex: 0 0 auto; }\r\n.tool{ display: inline-flex; align-items: center; gap: var(--sp-1); min-height: 28px; padding: 0 var(--sp-3);\r\n  border: 1px solid transparent; border-radius: 6px; background: transparent; color: var(--mm-text-2);\r\n  font-size: var(--fs-xs); font-weight: 600; cursor: pointer; white-space: nowrap;\r\n  transition: background var(--t-fast) ease-out, color var(--t-fast) ease-out, border-color var(--t-fast) ease-out; }\r\n.tool:hover{ background: var(--mm-surface); color: var(--mm-text-1); }\r\n.tool.on{ background: var(--mm-accent); border-color: var(--mm-accent); color: var(--mm-on-action); }\r\n.tool .k{ font-family: var(--font-num); font-size: 10px; line-height: 16px; padding: 0 4px; opacity: .8;\r\n  border: 1px solid currentColor; border-radius: 4px; }\r\n\r\n/* ---------- 输入 / 下拉（控件边界走 --mm-ctl-border，满足 3:1） ---------- */\r\ninput[type=\"text\"], input[type=\"search\"], input:not([type]), select, textarea{\r\n  min-height: 32px; padding: 0 var(--sp-2); background: var(--mm-surface); color: var(--mm-text-1);\r\n  border: 1px solid var(--mm-ctl-border); border-radius: var(--r-ctl);\r\n  transition: border-color var(--t-fast) ease-out, box-shadow var(--t-fast) ease-out; }\r\ninput:focus, select:focus, textarea:focus{ border-color: var(--mm-accent); box-shadow: 0 0 0 2px var(--mm-accent-tint); }\r\ninput:disabled, select:disabled{ opacity: .5; cursor: not-allowed; }\r\n::placeholder{ color: var(--mm-muted); opacity: 1; }\r\ninput[type=\"checkbox\"]{ accent-color: var(--mm-accent); }\r\ninput[type=\"range\"]{ accent-color: var(--mm-accent); }\r\n\r\n/* ---------- 主体 ---------- */\r\n#main{ flex: 1; display: flex; min-height: 0; }\r\n\r\n/* ---------- 物品栏 ---------- */\r\n#inv{ width: 320px; flex: 0 0 auto; background: var(--mm-surface); border-right: 1px solid var(--mm-line);\r\n  display: flex; flex-direction: column; min-height: 0; }\r\n#inv[hidden]{ display: none !important; }\r\n#invHead{ padding: var(--sp-2) var(--sp-3); border-bottom: 1px solid var(--mm-line); display: flex; flex-direction: column; gap: var(--sp-2); }\r\n#invHead .row{ display: flex; gap: var(--sp-2); align-items: center; }\r\n#invHead .inv-title{ font-size: var(--fs-xs); font-weight: 700; color: var(--mm-text-1); }\r\n#invCount.cnt{ font-size: 10.5px; color: var(--mm-muted); font-variant-numeric: tabular-nums; }\r\n#q{ flex: 1; min-width: 0; }\r\n#ns{ max-width: 160px; }\r\n#tabs{ display: flex; gap: var(--sp-1); flex-wrap: wrap; }\r\n#tabs .btn{ min-height: 24px; padding: 0 var(--sp-2); font-size: var(--fs-xs); font-weight: 400; }\r\n#invFoot{ padding: var(--sp-2) var(--sp-3); border-top: 1px solid var(--mm-line);\r\n  display: flex; align-items: center; gap: var(--sp-2); font-size: var(--fs-xs); color: var(--mm-text-2); }\r\n#invFoot .btn{ min-height: 24px; padding: 0 var(--sp-2); }\r\n#selLine{ padding: var(--sp-2) var(--sp-3); border-top: 1px solid var(--mm-line); font-size: var(--fs-xs);\r\n  color: var(--mm-text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\r\n#selLine b{ color: var(--mm-text-1); }\r\n\r\n/* 网格：格子即\"可点击目标\"，同样要有 hover / focus / active / 选中 态。\r\n   E6：44px 是可点性临界线（WCAG AAA 是底线不是舒适线）→ 固定 48px 轨道（Material 基准，\r\n   首次点击成功率 +11%）；用固定轨道而不是 minmax(48,1fr)，格子尺寸不随面板宽度漂移 */\r\n#grid{ flex: 1; overflow-y: auto; padding: var(--sp-2); display: grid;\r\n  grid-template-columns: repeat(auto-fill, 48px); justify-content: start; gap: var(--sp-1); align-content: start; }\r\n.cell{ position: relative; aspect-ratio: 1; background: var(--mm-bg-2); border: 1px solid var(--mm-line);\r\n  border-radius: var(--r-ctl); display: flex; align-items: center; justify-content: center;\r\n  cursor: pointer; overflow: hidden; transition: border-color var(--t-fast) ease-out, box-shadow var(--t-fast) ease-out,\r\n  background var(--t-fast) ease-out, transform var(--t-fast) ease-out; }\r\n.cell:hover{ border-color: var(--mm-accent); box-shadow: var(--sh-sm); background: var(--mm-surface); }\r\n.cell:active{ transform: scale(.98); }\r\n.cell.sel{ border-color: var(--mm-accent); box-shadow: 0 0 0 2px var(--mm-accent) inset; background: var(--mm-accent-tint); }\r\n.cell img{ width: 100%; height: 100%; image-rendering: pixelated; object-fit: contain; }\r\n/* 图标缺失时的文字兜底：默认隐藏，由 JS 切成 block（`.cell` 已有 overflow:hidden 负责裁切） */\r\n.cell .fb{ display: none; font-size: 10px; color: var(--mm-text-2); text-align: center; padding: 2px;\r\n  line-height: 1.15; overflow: hidden; word-break: break-word; max-height: 100%; }\r\n\r\n/* ---------- 视口 ---------- */\r\n#stageWrap{ flex: 1; position: relative; min-width: 0; background: var(--mm-canvas); }\r\n#stage{ display: block; width: 100%; height: 100%; touch-action: none; cursor: crosshair; }\r\n/* 操作提示：浅色主题下纯 text-shadow 会糊，改成半透明底的\"浮层\"，两种主题都读得清 */\r\n#overlay{ position: absolute; left: var(--sp-3); top: var(--sp-3); font: var(--fs-xs)/1.6 var(--font-num);\r\n  color: var(--mm-text-2); pointer-events: none; padding: var(--sp-2) var(--sp-2) var(--sp-2) var(--sp-3);\r\n  background: color-mix(in srgb, var(--mm-surface) 78%, transparent);\r\n  border: 1px solid var(--mm-line); border-radius: var(--r-ctl);\r\n  display: flex; align-items: center; gap: var(--sp-2); }\r\n#overlay[hidden]{ display: none; }\r\n#overlay .tx{ white-space: pre; }\r\n/* 收起按钮（2026-10-12）：提示条压在视口左上角、与建筑重叠 ⇒ 给一个\"这一次先别挡\"的出口。\r\n   ★ 为什么不做成工具条上的开关：那会变成第 15 个常驻控件 —— 用户抱怨的正是按钮过多。\r\n     出口放在\"碍事的东西自己身上\"才不增加认知负担。浮层本身 pointer-events:none，只有按钮接管。 */\r\n#overlay .x{ pointer-events: auto; flex: 0 0 auto; width: 18px; height: 18px; min-height: 0; padding: 0;\r\n  display: inline-flex; align-items: center; justify-content: center; line-height: 1;\r\n  font-size: 12px; font-family: var(--font-num); background: var(--mm-surface); color: var(--mm-text-2);\r\n  border: 1px solid var(--mm-line); border-radius: var(--r-full); cursor: pointer; }\r\n#overlay .x:hover{ border-color: var(--mm-accent); color: var(--mm-accent); background: var(--mm-accent-tint); }\r\n#err{ position: absolute; left: var(--sp-3); right: var(--sp-3); bottom: var(--sp-3); color: var(--mm-err-text);\r\n  font: var(--fs-xs)/1.5 var(--font-num); white-space: pre-wrap; pointer-events: none;\r\n  background: color-mix(in srgb, var(--mm-surface) 88%, transparent);\r\n  border-left: 2px solid var(--mm-err-text); border-radius: var(--r-ctl); padding: var(--sp-2) var(--sp-3); }\r\n/* loading 态：遮罩 + 指示器（skill §7） */\r\n#busy{ position: absolute; inset: 0; display: none; align-items: center; justify-content: center; gap: var(--sp-2);\r\n  background: color-mix(in srgb, var(--mm-canvas) 72%, transparent); color: var(--mm-text-1); font-size: var(--fs-sm); }\r\n#busy.on{ display: flex; }\r\n#busy::before{ content: \"\"; width: 14px; height: 14px; border: 2px solid var(--mm-accent);\r\n  border-right-color: transparent; border-radius: var(--r-full); animation: mcp-spin var(--t-slow) linear infinite; }\r\n@keyframes mcp-spin{ to{ transform: rotate(360deg); } }\r\n\r\n/* ---------- L3 上下文浮层 · 投影（视口右上，ViewCube 正下方） ---------- */\r\n/* 为什么不放底部：底部整条被 #err（left/right: sp-3）占着，框选动作条又居中在底部；\r\n   左上角是操作提示条。视口右上往下是唯一不与既有浮层打架的空位。\r\n   ★ 与 ViewCube 的间距必须留够：ViewCube 是 top:sp-3 + 92px 高 ⇒ 这里从 sp-3+92+sp-2 起。\r\n     （写死 top:sp-3 就会**压在 ViewCube 上**，闸门 (U29c) 用矩形相交守着这条。） */\r\n.proj-bar{ position: absolute; right: var(--sp-3); top: calc(var(--sp-3) + 92px + var(--sp-2));\r\n  width: 176px; display: flex; flex-direction: column; gap: 4px; align-items: stretch;\r\n  padding: var(--sp-2); background: var(--mm-surface); border: 1px solid var(--mm-accent);\r\n  border-radius: var(--r-card); box-shadow: var(--sh-lg); z-index: var(--z-sticky); }\r\n.proj-bar[hidden]{ display: none; }\r\n.proj-bar .pb-title{ font-size: var(--fs-xs); font-weight: 600; color: var(--mm-text-2); padding: 0 var(--sp-1); }\r\n.proj-bar .btn{ min-height: 28px; padding: 0 var(--sp-2); font-size: var(--fs-xs); text-align: left; }\r\n\r\n/* ---------- 选区动作条（框选拖出矩形、释放后浮出：已选区 N 格 + 填充/清空/取消） ---------- */\r\n#selBar{ position: absolute; left: 50%; bottom: var(--sp-4); transform: translateX(-50%);\r\n  display: flex; align-items: center; gap: var(--sp-2); padding: var(--sp-2) var(--sp-3);\r\n  background: var(--mm-surface); border: 1px solid var(--mm-accent); border-radius: var(--r-full);\r\n  box-shadow: var(--sh-lg); z-index: var(--z-sticky); }\r\n#selBar[hidden]{ display: none; }\r\n#selBar .lb{ font-size: var(--fs-xs); color: var(--mm-text-2); white-space: nowrap; }\r\n#selBar .lb .num{ color: var(--mm-text-1); font-family: var(--font-num); font-variant-numeric: tabular-nums; }\r\n#selBar .btn{ min-height: 28px; padding: 0 var(--sp-3); font-size: var(--fs-xs); }\r\n\r\n/* ---------- 会话恢复条（U3：打开面板时非空会话显示；仿定稿原型置视口右上） ---------- */\r\n#restoreToast{ position: absolute; top: var(--sp-3); right: var(--sp-3);\r\n  background: var(--mm-surface); border: 1px solid var(--mm-accent); border-radius: var(--r-card);\r\n  box-shadow: var(--sh-lg); padding: var(--sp-3) var(--sp-4); min-width: 260px; max-width: 330px; z-index: var(--z-modal);\r\n  display: flex; flex-direction: column; gap: var(--sp-2); pointer-events: auto; }\r\n#restoreToast .t{ font-size: var(--fs-sm); font-weight: 700; color: var(--mm-text-1); display: flex; align-items: center; gap: var(--sp-1); }\r\n#restoreToast .s{ margin: 0; font-size: var(--fs-xs); color: var(--mm-text-2); line-height: 1.5; }\r\n#restoreToast .row{ display: flex; gap: var(--sp-2); justify-content: flex-end; }\r\n#restoreToast .row .btn{ min-height: 28px; padding: 0 var(--sp-3); font-size: var(--fs-xs); }\r\n/* 出现/消失动效（尊重 prefers-reduced-motion） */\r\n#restoreToast{ opacity: 0; transform: translateY(-4px);\r\n  transition: opacity var(--t-base) ease-out, transform var(--t-base) ease-out; }\r\n#restoreToast.on{ opacity: 1; transform: none; }\r\n@media (prefers-reduced-motion: reduce){\r\n  #restoreToast{ transition: none; }\r\n}\r\n\r\n/* ---------- 状态栏：定高 + 不换行 + 溢出省略 ----------\r\n   （曾经是 flex-wrap:wrap，`#msg` 文字一变长就换行 ⇒ 视口高度变化 ⇒ 3D 画面\"放大缩小\"跳动） */\r\n#status{ display: flex; gap: var(--sp-4); align-items: center; padding: 0 var(--sp-3); background: var(--mm-surface);\r\n  border-top: 1px solid var(--mm-line); font-size: var(--fs-xs); color: var(--mm-text-2);\r\n  height: 32px; min-height: 32px; flex-wrap: nowrap; overflow: hidden; }\r\n#status > span{ white-space: nowrap; flex: 0 0 auto; }\r\n#status b{ color: var(--mm-text-1); font-weight: 500; font-variant-numeric: tabular-nums; }\r\n/* E5：状态栏分组 —— 组名做成小徽标，组含义靠 .grp 的 title 悬浮解释；em 是组内分隔点 */\r\n#status .grp{ display: inline-flex; align-items: center; gap: var(--sp-1); }\r\n#status .grp i{ font-style: normal; font-size: var(--fs-xs); color: var(--mm-text-2); background: var(--mm-bg-2);\r\n  border-radius: var(--r-full); padding: 0 var(--sp-2); line-height: 20px; }\r\n#status .grp em{ font-style: normal; color: var(--mm-muted); }\r\n#status .spacer{ flex: 1 1 auto; }\r\n#msg{ flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; max-width: 42ch; color: var(--mm-ok-text);\r\n  transition: opacity var(--t-slow) ease-out; }\r\n#msg.fade{ opacity: 0; }\r\n/* 空态占位（2026-10-11：用户问「状态栏左边那条空白是什么」——没消息时给一个弱化提示，它就不是「坏掉的空槽」） */\r\n#msg:empty::before{ content: '就绪'; opacity: .38; }\r\n#msg.warn, #msg.err{ padding: 1px var(--sp-2); border-radius: var(--r-full); }\r\n#msg.warn{ color: var(--mm-warn-text); background: color-mix(in srgb, var(--mm-warning) 14%, transparent); }\r\n#msg.err{ color: var(--mm-err-text); background: color-mix(in srgb, var(--mm-danger) 14%, transparent); }\r\n#stat{ flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; color: var(--mm-muted); }\r\n\r\n/* ---------- 对话框（Modal：遮罩 0.45 / 圆角 12 / 阴影 lg / Esc 关闭由 JS 负责） ---------- */\r\n#dlg{ position: fixed; inset: 0; background: var(--mm-scrim); display: none; align-items: center; justify-content: center; z-index: var(--z-modal); }\r\n#dlg.on{ display: flex; }\r\n#dlgBox{ background: var(--mm-surface); border: 1px solid var(--mm-line); border-radius: var(--r-card);\r\n  width: min(640px, 92vw); max-height: 80vh; display: flex; flex-direction: column; box-shadow: var(--sh-lg);\r\n  animation: mcp-pop var(--t-base) ease-out; }\r\n@keyframes mcp-pop{ from{ opacity: 0; transform: translateY(6px); } to{ opacity: 1; transform: none; } }\r\n#dlgBox header{ padding: var(--sp-3) var(--sp-4); border-bottom: 1px solid var(--mm-line); display: flex; align-items: center; gap: var(--sp-2); }\r\n#dlgBox .body{ overflow: auto; padding: var(--sp-2) var(--sp-4) var(--sp-4); }\r\n#dlgBox table{ width: 100%; border-collapse: collapse; font-size: var(--fs-xs); }\r\n#dlgBox th, #dlgBox td{ text-align: left; padding: var(--sp-2) var(--sp-3); border-bottom: 1px solid var(--mm-line); }\r\n#dlgBox th{ color: var(--mm-text-2); font-weight: 500; background: var(--mm-bg-2);\r\n  position: sticky; top: 0; }\r\n#dlgBox td.n{ text-align: right; font-variant-numeric: tabular-nums; font-family: var(--font-num); }\r\n#dlgBox footer{ padding: var(--sp-3) var(--sp-4); border-top: 1px solid var(--mm-line); display: flex; gap: var(--sp-2); justify-content: flex-end; }\r\n\r\n/* ---------- 空态（Table/列表空态：居中说明） ---------- */\r\n.hint[style*=\"grid-column\"]{ display: block; text-align: center; color: var(--mm-muted); }\r\n\r\n/* ---------- 滚动条：跟随主题，不做装饰 ---------- */\r\n#grid, #dlgBox .body, .body{ scrollbar-color: var(--mm-muted) transparent; scrollbar-width: thin; }\r\n#grid::-webkit-scrollbar{ width: 10px; }\r\n#grid::-webkit-scrollbar-thumb{ background: var(--mm-bg-2); border: 3px solid transparent; background-clip: content-box; border-radius: var(--r-full); }\r\n#grid::-webkit-scrollbar-thumb:hover{ background: var(--mm-muted); background-clip: content-box; }\r\n\r\n/* ---------- 响应式（skill §5：断点 768 / 1280；宿主面板可能很窄） ---------- */\r\n@media (max-width: 1280px){ #inv{ width: 280px; } }\r\n@media (max-width: 960px){\r\n  #inv{ width: 232px; }\r\n  #bar .brand small{ display: none; }      /* 窄的时候先舍去副标题，保住操作按钮 */\r\n}\r\n@media (max-width: 768px){\r\n  #main{ flex-direction: column; }\r\n  #inv{ width: 100%; height: 44%; border-right: none; border-bottom: 1px solid var(--mm-line); }\r\n  #status{ gap: var(--sp-3); }\r\n}\r\n\r\n/* ---------- 动效降级 ---------- */\r\n@media (prefers-reduced-motion: reduce){\r\n  *, *::before{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }\r\n  .btn:active, .cell:active{ transform: none; }\r\n}\r\n\r\n\r\n/* ==================== 下拉分组 + 项目列表 + 保存状态（2026-10-11） ====================\r\n   为什么自己做 .grp/.grp-pop 而不用 <details>：需要\"同时只开一个 / 点外部关闭 / Esc 关闭\"\r\n   三条交互，<details> 的原生行为不完全可控（且 Shadow DOM 下的 marker 样式不可靠）。 */\r\n.grp{ position: relative; display: inline-flex; align-items: center; }\r\n.grp-head{ display: inline-flex; align-items: center; gap: var(--sp-1); }\r\n.grp-head .caret{ width: 0; height: 0; border-left: 4px solid transparent; border-right: 4px solid transparent;\r\n  border-top: 5px solid currentColor; opacity: .7; transition: transform var(--t-fast); }\r\n.grp-head[aria-expanded=\"true\"] .caret{ transform: rotate(180deg); }\r\n.grp-head .dot{ width: 6px; height: 6px; border-radius: var(--r-full); background: var(--mm-accent); }\r\n/* 组里有\"开着\"的开关时，组标题自身也点亮（否则折叠起来就看不出来了） */\r\n.grp-head.on{ background: var(--mm-accent-tint); border-color: var(--mm-accent); color: var(--mm-accent); font-weight: 600; }\r\n.grp-pop{ position: absolute; top: calc(100% + 6px); left: 0; z-index: var(--z-drop); min-width: 172px;\r\n  display: flex; flex-direction: column; gap: var(--sp-1); padding: var(--sp-2);\r\n  background: var(--mm-surface); border: 1px solid var(--mm-line); border-radius: var(--r-card);\r\n  box-shadow: var(--sh-lg); }\r\n.grp-pop.atright{ left: auto; right: 0; }\r\n.grp-pop[hidden]{ display: none; }\r\n.grp-pop.wide{ min-width: 276px; }\r\n.grp-pop .btn{ justify-content: flex-start; width: 100%; min-height: 30px; font-size: var(--fs-sm); }\r\n.grp-pop .btn.danger{ color: var(--mm-danger); border-color: color-mix(in srgb, var(--mm-danger) 45%, transparent); }\r\n.grp-pop .btn.danger:hover{ background: color-mix(in srgb, var(--mm-danger) 10%, transparent); border-color: var(--mm-danger); }\r\n.pop-title{ font-size: var(--fs-xs); color: var(--mm-muted); padding: 0 var(--sp-1) var(--sp-1); }\r\n.pop-sep{ height: 1px; background: var(--mm-line); margin: var(--sp-1) 0; }\r\n.pop-note{ font-size: var(--fs-xs); color: var(--mm-muted); padding: var(--sp-1) var(--sp-1) 0; line-height: 1.5; }\r\n.proj-list{ display: flex; flex-direction: column; gap: 2px; max-height: 240px; overflow: auto; }\r\n.proj-row{ display: flex; align-items: center; gap: var(--sp-2); width: 100%; text-align: left;\r\n  min-height: 30px; padding: 0 var(--sp-2); border: 1px solid transparent; border-radius: var(--r-ctl);\r\n  background: transparent; color: var(--mm-text-1); font: inherit; font-size: var(--fs-sm); cursor: pointer; }\r\n.proj-row:hover{ background: var(--mm-bg-2); }\r\n.proj-row.cur{ background: var(--mm-accent-tint); border-color: var(--mm-accent); font-weight: 600; }\r\n.proj-row .nm{ flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\r\n.proj-row .meta{ flex: 0 0 auto; font-family: var(--font-num); font-size: var(--fs-xs); color: var(--mm-muted); }\r\n.proj-empty{ font-size: var(--fs-xs); color: var(--mm-muted); padding: var(--sp-2); text-align: center; }\r\n.saveState{ font-size: var(--fs-xs); color: var(--mm-muted); white-space: nowrap; font-variant-numeric: tabular-nums; }\r\n.saveState.warn{ color: var(--mm-warn-text); }\r\n.saveState.err{ color: var(--mm-err-text); }\r\n\r\n/* ==================== ViewCube（右下角小方块） ==================== */\r\n/* 2026-10-12（用户要求）：视图立方体从右下角**移到右上角** —— 右下角与状态栏同侧、更靠近操作热区；\r\n   右上角是空的（操作提示在左上、窗口内缩在左下）。 */\r\n#vcube{ position: absolute; right: var(--sp-3); top: var(--sp-3); width: 92px; height: 92px;\r\n  background: color-mix(in srgb, var(--mm-surface) 84%, transparent); border: 1px solid var(--mm-line);\r\n  border-radius: var(--r-card); box-shadow: var(--sh-sm); touch-action: none; cursor: grab; outline: none; }\r\n#vcube:hover{ border-color: var(--mm-accent); }\r\n#vcube:focus-visible{ border-color: var(--mm-accent); box-shadow: 0 0 0 2px var(--mm-accent-tint); }\r\n#vcube:active{ cursor: grabbing; }\r\n#vcube canvas{ display: block; width: 100%; height: 100%; }\r\n#err{ right: var(--sp-3); }   /* ViewCube 移到右上角之后，底部不再需要给它让位 */\r\n\r\n/* 坐标轴指示器（2026-10-12）：左下角。三根线由 JS 按视图矩阵给旋转角，字母在末端。\r\n   为什么需要它：轴的颜色约定（X 红 / Y 绿 / Z 蓝）是 Minecraft 的，而 Blender/3ds Max 一类\r\n   软件是\"Z 竖直、Y 朝里\"⇒ 用户光看颜色会认错（真实反馈：把竖着的绿线当成了 Z 轴）。 */\r\n#axisGizmo{ position:absolute; left:calc(var(--sp-3) + 4px); bottom:calc(var(--sp-3) + 4px);\r\n  width:96px; height:96px; pointer-events:none; z-index:6; opacity:.95;\r\n  filter:drop-shadow(0 1px 2px rgba(0,0,0,.35)); }\r\n#axisGizmo::after{ content:''; position:absolute; left:50%; top:50%; width:5px; height:5px;\r\n  margin:-2.5px 0 0 -2.5px; border-radius:50%; background:currentColor; opacity:.55; }\r\n/* ★ 尺寸按\"能看清字母\"来定（2026-10-12 第一次给 62px/10px 字，用户截图里几乎看不见）：\r\n   半径 38px + 13px 字号 —— 在 1440 宽的视口里一眼能读出 X/Y/Z。 */\r\n#axisGizmo .axl{ position:absolute; left:50%; top:50%; height:3px; width:38px;\r\n  transform-origin:0 50%; will-change:transform; border-radius:2px; }\r\n#axisGizmo .axl i{ position:absolute; left:41px; top:-10px; font:700 13px/20px var(--font-num);\r\n  font-style:normal; letter-spacing:0; }\r\n#axisGizmo .axl-x{ background:#e0554a; color:#e0554a; }\r\n#axisGizmo .axl-y{ background:#43c04a; color:#43c04a; }\r\n#axisGizmo .axl-z{ background:#4f7dfa; color:#4f7dfa; }\r\n\n.mcp-host{display:block;height:100%;min-height:0}\n";
